public interface DataProcessor {
    void process(byte[] data) throws Exception;
}

public class FileDataProcessor implements DataProcessor {
    @Override
    public void process(byte[] data) {
        // Core file writing logic
    }
}

// Composition in action: LoggingProcessor wraps any DataProcessor dynamically
public class LoggingDataProcessor implements DataProcessor {
    private final DataProcessor wrapped;

    public LoggingDataProcessor(DataProcessor wrapped) {
        this.wrapped = wrapped;
    }

    @Override
    public void process(byte[] data) throws Exception {
        long start = System.currentTimeMillis();
        try {
            wrapped.process(data);
        } finally {
            long duration = System.currentTimeMillis() - start;
            System.out.println("Processed bytes in: " + duration + "ms");
        }
    }
}
